
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_bkl2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_bkl2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.231203280737460e+00, -4.148350200858573e+00, -4.032310859979326e+00, -3.871691035500972e+00, -3.653093455703434e+00, -3.362746496359858e+00, -2.990375365599524e+00, -2.536322681341915e+00, -2.021710245773877e+00, -1.495382825413652e+00, -1.011795758021863e+00, -6.914563364643047e-01, -5.954894367308805e-01, -4.866870669278167e-01, -3.496399123978141e-01, -2.245475470613406e-01, -1.299936649178162e-01, -4.468289195348572e-02, -6.029205524552298e-03, -6.741774113089777e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


